# ------------------------------------------------------------------ banks
def banks_section():
    d = json.load(io.open(os.path.join(REPO, "plugins", "nadlan-config", "assets", "instruments", "data", "boi-mortgage.json"), encoding="utf-8"))
    bb = d["by_bank"]; lat = {r["bank"]: r for r in bb["latest"]["table"]}
    b = json.load(io.open(os.path.join(REPO, "docs", "research", "2026-11-06-mortgage-universe", "gov", "banks.json"), encoding="utf-8"))["banks"]
    key = {"Bank Leumi": "leumi", "Bank Hapoalim": "hapoalim", "Mizrahi-Tefahot Bank": "mizrahi", "Israel Discount Bank": "discount",
           "Mercantile Discount Bank": "mercantile", "First International Bank of Israel (FIBI)": "fibi", "Bank of Jerusalem": "jerusalem"}
    name = {"leumi": "לאומי", "hapoalim": "הפועלים", "mizrahi": "מזרחי־טפחות", "discount": "דיסקונט", "mercantile": "מרכנתיל",
            "fibi": "הבינלאומי", "jerusalem": "ירושלים"}
    rows = []
    for x in b:
        k = key.get(x["name_en"])
        if not k or not x.get("phones"):
            continue
        r = lat[k]
        num = x["phones"][0]["numbers"][0]; ext = ""
        if " ext. 4" in num:
            num, ext = num.split(" ext. 4")[0], "<small>שלוחה 4</small>"
        ph = '<bdi dir="ltr">%s</bdi>%s' % (num, ext)
        if "general" in x["phones"][0]["purpose"] or "no mortgage-specific" in x["phones"][0]["purpose"]:
            ph += "<small>מוקד כללי</small>"
        site = x["mortgage_site"]
        host = site.split("//", 1)[1].split("/", 1)[0].replace("www.", "")
        rows.append((r["irr"], ['%s' % name[k], "%.2f%%" % r["irr"], "%.2f%%" % r["fixed_nl"]["rate"], "%.2f%%" % r["prime"]["rate"],
                                "%.2f%%" % r["fixed_cpi"]["rate"], ph, L(site, host)]))
    rows.sort(key=lambda t: t[0])
    sysr = lat["system"]
    body = table("המשכנתאות בבנקים: הריבית הממוצעת בספטמבר 2026, האתר והטלפון",
                 "ריבית אפקטיבית שנתית במשכנתאות החדשות לפי בנק (בנק ישראל, קו המשווה, פורסם ב־20.10.2026). הטלפון והאתר מהאתר של כל בנק, נבדקו ב־6.11.2026. ממוין מהזול ליקר לפי הריבית הכוללת.",
                 ["בנק", "ריבית כוללת חזויה", "קבועה לא צמודה", "פריים", "קבועה צמודה", "מוקד משכנתאות", "אתר"], [r for _, r in rows], numcols=[1, 2, 3, 4])
    return ('<section id="mortgage-banks">\n<h2>הבנקים למשכנתאות: הריבית הממוצעת, האתר והטלפון</h2>\n'
            '<p class="nlx-ans">בספטמבר 2026 הריבית הכוללת החזויה הממוצעת במשכנתאות החדשות בכל הבנקים הייתה %.2f%%: מ־%.2f%% בבנק הבינלאומי '
            'עד %.2f%% בבנק ירושלים. אלה ממוצעים של כל ההלוואות בכל בנק, לא הצעה אישית; ההצעה שלכם תלויה בתמהיל, באחוז המימון ובהכנסה.</p>\n'
            % (sysr["irr"], lat["fibi"]["irr"], lat["jerusalem"]["irr"]) + body +
            '<p>בנק יהב מפנה לקוחות משכנתא למזרחי־טפחות, ובנקים אוצר החייל ומסד מקבוצת הבינלאומי מגישים בקשה דיגיטלית דרך אתר הבינלאומי. '
            'כל הבנקים בטבלה מקבלים בקשה למשכנתא באינטרנט. להשוואה בין הצעות שקיבלתם: <a href="#tool-offers">שלוש הצעות, טבלה אחת</a>.</p>\n'
            + BACK + '</section>\n')


